{
    "Comment": "CodeAnalysisWorkflowV3 - Per-file AI analysis with Lambda/Fargate routing",
    "StartAt": "TreeSitterAnalyzer",
    "States": {
        "TreeSitterAnalyzer": {
            "Type": "Task",
            "Resource": "arn:aws:states:::lambda:invoke",
            "Parameters": {
                "FunctionName": "arn:aws:lambda:us-east-1:376129851858:function:TreeSitterAnalyzerV3",
                "Payload.$": "$"
            },
            "ResultSelector": {
                "statusCode.$": "$.Payload.statusCode",
                "body.$": "States.StringToJson($.Payload.body)"
            },
            "ResultPath": "$.treesitter_result",
            "Next": "CheckTreeSitterStatus",
            "Retry": [
                {
                    "ErrorEquals": [
                        "Lambda.ServiceException",
                        "Lambda.AWSLambdaException",
                        "Lambda.SdkClientException"
                    ],
                    "IntervalSeconds": 2,
                    "MaxAttempts": 3,
                    "BackoffRate": 2
                }
            ],
            "Catch": [
                {
                    "ErrorEquals": [
                        "States.ALL"
                    ],
                    "ResultPath": "$.error",
                    "Next": "AnalysisFailed"
                }
            ]
        },
        "CheckTreeSitterStatus": {
            "Type": "Choice",
            "Choices": [
                {
                    "Variable": "$.treesitter_result.body.status",
                    "StringEquals": "success",
                    "Next": "PrepareBedrockMap"
                },
                {
                    "Variable": "$.treesitter_result.body.status",
                    "StringEquals": "partial_success",
                    "Next": "PrepareBedrockMap"
                }
            ],
            "Default": "AnalysisFailed"
        },
        "PrepareBedrockMap": {
            "Type": "Task",
            "Resource": "arn:aws:states:::lambda:invoke",
            "Parameters": {
                "FunctionName": "arn:aws:lambda:us-east-1:376129851858:function:PrepareBedrockMapV3",
                "Payload": {
                    "job_id.$": "$.treesitter_result.body.job_id",
                    "scout_account_id.$": "$.scout_account_id",
                    "application_name.$": "$.application_name",
                    "source_hash.$": "$.source_hash",
                    "total_files.$": "$.treesitter_result.body.total_files",
                    "successful_files.$": "$.treesitter_result.body.successful_files"
                }
            },
            "ResultSelector": {
                "lambda_files.$": "$.Payload.lambda_files",
                "fargate_files.$": "$.Payload.fargate_files",
                "summary.$": "$.Payload.summary"
            },
            "ResultPath": "$.prepare_result",
            "Next": "CheckFilesToAnalyze",
            "Retry": [
                {
                    "ErrorEquals": [
                        "Lambda.ServiceException",
                        "Lambda.AWSLambdaException",
                        "Lambda.SdkClientException"
                    ],
                    "IntervalSeconds": 2,
                    "MaxAttempts": 3,
                    "BackoffRate": 2
                }
            ],
            "Catch": [
                {
                    "ErrorEquals": [
                        "States.ALL"
                    ],
                    "ResultPath": "$.error",
                    "Next": "AnalysisFailed"
                }
            ]
        },
        "CheckFilesToAnalyze": {
            "Type": "Choice",
            "Choices": [
                {
                    "Or": [
                        {
                            "Variable": "$.prepare_result.summary.lambda_files_count",
                            "NumericGreaterThan": 0
                        },
                        {
                            "Variable": "$.prepare_result.summary.fargate_files_count",
                            "NumericGreaterThan": 0
                        }
                    ],
                    "Next": "ProcessFiles"
                }
            ],
            "Default": "NoFilesToAnalyze"
        },
        "ProcessFiles": {
            "Type": "Parallel",
            "ResultPath": "$.processing_results",
            "Branches": [
                {
                    "StartAt": "CheckLambdaFiles",
                    "States": {
                        "CheckLambdaFiles": {
                            "Type": "Choice",
                            "Choices": [
                                {
                                    "Variable": "$.prepare_result.summary.lambda_files_count",
                                    "NumericGreaterThan": 0,
                                    "Next": "LambdaMap"
                                }
                            ],
                            "Default": "NoLambdaFiles"
                        },
                        "LambdaMap": {
                            "Type": "Map",
                            "ItemsPath": "$.prepare_result.lambda_files",
                            "MaxConcurrency": 10,
                            "Iterator": {
                                "StartAt": "AnalyzeFileWithLambda",
                                "States": {
                                    "AnalyzeFileWithLambda": {
                                        "Type": "Task",
                                        "Resource": "arn:aws:states:::lambda:invoke",
                                        "Parameters": {
                                            "FunctionName": "arn:aws:lambda:us-east-1:376129851858:function:BedrockAnalyzerPerFileV3",
                                            "Payload.$": "$"
                                        },
                                        "ResultSelector": {
                                            "statusCode.$": "$.Payload.statusCode",
                                            "body.$": "States.StringToJson($.Payload.body)"
                                        },
                                        "Retry": [
                                            {
                                                "ErrorEquals": [
                                                    "Lambda.ServiceException",
                                                    "Lambda.AWSLambdaException",
                                                    "Lambda.SdkClientException"
                                                ],
                                                "IntervalSeconds": 2,
                                                "MaxAttempts": 3,
                                                "BackoffRate": 2
                                            }
                                        ],
                                        "Catch": [
                                            {
                                                "ErrorEquals": [
                                                    "States.ALL"
                                                ],
                                                "ResultPath": "$.error",
                                                "Next": "LambdaFileFailed"
                                            }
                                        ],
                                        "End": true
                                    },
                                    "LambdaFileFailed": {
                                        "Type": "Pass",
                                        "Result": {
                                            "status": "failed",
                                            "message": "Lambda file analysis failed"
                                        },
                                        "End": true
                                    }
                                }
                            },
                            "End": true
                        },
                        "NoLambdaFiles": {
                            "Type": "Pass",
                            "Result": {
                                "status": "skipped",
                                "message": "No small files to process with Lambda"
                            },
                            "End": true
                        }
                    }
                },
                {
                    "StartAt": "CheckFargateFiles",
                    "States": {
                        "CheckFargateFiles": {
                            "Type": "Choice",
                            "Choices": [
                                {
                                    "Variable": "$.prepare_result.summary.fargate_files_count",
                                    "NumericGreaterThan": 0,
                                    "Next": "FargateMap"
                                }
                            ],
                            "Default": "NoFargateFiles"
                        },
                        "FargateMap": {
                            "Type": "Map",
                            "ItemsPath": "$.prepare_result.fargate_files",
                            "MaxConcurrency": 5,
                            "Iterator": {
                                "StartAt": "AnalyzeFileWithFargate",
                                "States": {
                                    "AnalyzeFileWithFargate": {
                                        "Type": "Task",
                                        "Resource": "arn:aws:states:::ecs:runTask.sync",
                                        "Parameters": {
                                            "Cluster": "code-analysis-cluster",
                                            "TaskDefinition": "bedrock-analyzer-fargate:6",
                                            "LaunchType": "FARGATE",
                                            "NetworkConfiguration": {
                                                "AwsvpcConfiguration": {
                                                    "Subnets": [
                                                        "subnet-05a88f702ca6880c9",
                                                        "subnet-07eca6716104acb0b"
                                                    ],
                                                    "SecurityGroups": [
                                                        "sg-03208a7865d2ff78e"
                                                    ],
                                                    "AssignPublicIp": "ENABLED"
                                                }
                                            },
                                            "Overrides": {
                                                "ContainerOverrides": [
                                                    {
                                                        "Name": "bedrock-analyzer",
                                                        "Environment": [
                                                            {
                                                                "Name": "JOB_ID",
                                                                "Value.$": "$.job_id"
                                                            },
                                                            {
                                                                "Name": "FILE_NAME",
                                                                "Value.$": "$.file_name"
                                                            },
                                                            {
                                                                "Name": "SCOUT_ACCOUNT_ID",
                                                                "Value.$": "$.scout_account_id"
                                                            },
                                                            {
                                                                "Name": "APPLICATION_NAME",
                                                                "Value.$": "$.application_name"
                                                            },
                                                            {
                                                                "Name": "SOURCE_HASH",
                                                                "Value.$": "$.source_hash"
                                                            },
                                                            {
                                                                "Name": "FILE_ANALYSIS_S3_KEY",
                                                                "Value.$": "$.file_analysis_s3_key"
                                                            }
                                                        ]
                                                    }
                                                ]
                                            }
                                        },
                                        "Retry": [
                                            {
                                                "ErrorEquals": [
                                                    "States.TaskFailed"
                                                ],
                                                "IntervalSeconds": 5,
                                                "MaxAttempts": 2,
                                                "BackoffRate": 2
                                            }
                                        ],
                                        "Catch": [
                                            {
                                                "ErrorEquals": [
                                                    "States.ALL"
                                                ],
                                                "ResultPath": "$.error",
                                                "Next": "FargateFileFailed"
                                            }
                                        ],
                                        "End": true
                                    },
                                    "FargateFileFailed": {
                                        "Type": "Pass",
                                        "Result": {
                                            "status": "failed",
                                            "message": "Fargate file analysis failed"
                                        },
                                        "End": true
                                    }
                                }
                            },
                            "End": true
                        },
                        "NoFargateFiles": {
                            "Type": "Pass",
                            "Result": {
                                "status": "skipped",
                                "message": "No large files to process with Fargate"
                            },
                            "End": true
                        }
                    }
                }
            ],
            "Next": "GenerateSummary"
        },
        "NoFilesToAnalyze": {
            "Type": "Pass",
            "Result": {
                "status": "success",
                "message": "No COBOL_PROGRAM files to analyze (all files were copybooks, DCLGENs, or other non-COBOL types)"
            },
            "ResultPath": "$.workflow_result",
            "Next": "GenerateSummary"
        },
        "GenerateSummary": {
            "Type": "Task",
            "Resource": "arn:aws:states:::lambda:invoke",
            "Parameters": {
                "FunctionName": "arn:aws:lambda:us-east-1:376129851858:function:SummaryGeneratorV3",
                "Payload": {
                    "job_id.$": "$.treesitter_result.body.job_id",
                    "scout_account_id.$": "$.scout_account_id",
                    "application_name.$": "$.application_name",
                    "source_hash.$": "$.source_hash"
                }
            },
            "ResultPath": "$.summary_result",
            "Next": "AnalysisComplete",
            "Retry": [
                {
                    "ErrorEquals": [
                        "Lambda.ServiceException",
                        "Lambda.AWSLambdaException",
                        "Lambda.SdkClientException"
                    ],
                    "IntervalSeconds": 2,
                    "MaxAttempts": 3,
                    "BackoffRate": 2
                }
            ],
            "Catch": [
                {
                    "ErrorEquals": [
                        "States.ALL"
                    ],
                    "ResultPath": "$.summary_error",
                    "Next": "AnalysisComplete"
                }
            ]
        },
        "AnalysisComplete": {
            "Type": "Pass",
            "Result": {
                "status": "success",
                "message": "Code analysis workflow V3 completed successfully (with Lambda + Fargate routing + V2-compatible summary)"
            },
            "ResultPath": "$.workflow_result",
            "End": true
        },
        "AnalysisFailed": {
            "Type": "Fail",
            "Error": "AnalysisWorkflowFailed",
            "Cause": "Code analysis workflow failed. Check CloudWatch logs for details."
        }
    }
}
